# Let me check 4-connectivity (not 8):
# An 8 stays if it has at least one 4-connected neighbor that is also 8

def has_4(vin, i, j):
    h, w = len(vin), len(vin[0])
    for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
        ni, nj = i + di, j + dj
        if 0 <= ni < h and 0 <= nj < w:
            if vin[ni][nj] == 8:
                return True
    return False

# Test this
def compute_output(grid):
    h, w = len(grid), len(grid[0])
    out = copy.deepcopy(grid)
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 8:
                if not has_4(grid, i, j):
                    out[i][j] = 3
    return out

